import datetime
import datetime as dt
import time
import unittest
from fractions import Fraction

from tally import allocate, duration, fields, intervals, ledger, schedule


def _raises(fn, *args):
    try:
        fn(*args)
    except ValueError:
        return True
    return False


def _fast(fn, seconds):
    start = time.perf_counter()
    fn()
    return time.perf_counter() - start < seconds


class TallyTest(unittest.TestCase):

    def test_split_even(self):
        self.assertEqual(allocate.apportion(90, [1, 1, 1]), [30, 30, 30])

    def test_split_thirds(self):
        self.assertEqual(allocate.apportion(100, [1, 1, 1]), [34, 33, 33])

    def test_format_amount(self):
        self.assertEqual(allocate.format_amount(1234), '£12.34')

    def test_merge_overlap(self):
        self.assertEqual(intervals.merge([(1, 5), (3, 8)]), [(1, 8)])

    def test_merge_touching(self):
        self.assertEqual(intervals.merge([(1, 3), (3, 6)]), [(1, 6)])

    def test_free_slots(self):
        self.assertEqual(intervals.free_slots([(10, 12)], 9, 17), [(9, 10), (12, 17)])

    def test_parse_basic(self):
        self.assertEqual(duration.parse('1h30m'), 5400)

    def test_parse_rejects_junk(self):
        with self.assertRaises(ValueError):
            duration.parse('1h junk')

    def test_fields_basic(self):
        self.assertEqual(fields.parse_fields('a=1| b = two '), {'a': '1', 'b': 'two'})

    def test_fields_quoted(self):
        self.assertEqual(fields.parse_fields("a='x|y'"), {'a': 'x|y'})

    def test_bill_basic(self):
        self.assertEqual(ledger.bill([('Ann', '1h'), ('Bob', '30m')], 1200), [('Ann', 1200), ('Bob', 600)])

    def test_bill_same_name(self):
        self.assertEqual(ledger.bill([('Ann', '1h'), (' ann', '1h')], 1200), [('Ann', 2400)])

    def test_schedule_quarter_hour(self):
        self.assertEqual(schedule.next_run('*/15 * * * *', dt.datetime(2026, 5, 4, 10, 7)), datetime.datetime(2026, 5, 4, 10, 15))

    def test_schedule_daily(self):
        self.assertEqual(schedule.next_run('@daily', dt.datetime(2026, 5, 4, 10, 7)), datetime.datetime(2026, 5, 5, 0, 0))

    def test_schedule_matches(self):
        self.assertEqual(schedule.matches('30 9 * * *', dt.datetime(2026, 5, 4, 9, 30, 15)), True)

    def test_schedule_rejects(self):
        with self.assertRaises(ValueError):
            schedule.next_run('60 * * * *', dt.datetime(2026, 5, 4))


if __name__ == "__main__":
    unittest.main()

